# Generate AME bare-metal self-check tests.

from __future__ import annotations

import argparse
import re
from pathlib import Path


SCRIPT_DIR = Path(__file__).resolve().parent
SAIL_AME_ROOT = SCRIPT_DIR.parents[2]
UNIT_BITS = 8
SQUARE_ELEMS = 64


HEADER = [
    "# Copyright (c) Qualcomm Technologies, Inc. and/or its subsidiaries.",
    "# SPDX-License-Identifier: BSD-3-Clause-Clear",
    "#",
    "# Auto-generated by test/ame/gen/gen_ame_tests.py. Do not edit by hand.",
    "",
    '.include "test.inc"',
    '.include "ame_macros.inc"',
    "",
]


def asm_header(description: list[str]) -> list[str]:
    lines = HEADER.copy()
    if description:
        lines.insert(4, "#")
        for line in reversed(description):
            lines.insert(5, f"# {line}")
    lines.extend([".text", ""])
    return lines


def data_directive(element_bits: int) -> str:
    return {
        8: ".byte",
        16: ".half",
        32: ".word",
        64: ".dword",
    }[element_bits]


def hex_value(value: int, element_bits: int) -> str:
    return f"0x{value & ((1 << element_bits) - 1):0{element_bits // 4}x}"


def nregs_for_dtype(element_bits: int, unit_bits: int = UNIT_BITS) -> int:
    return max(1, element_bits // unit_bits)


def parse_ame_macros(path: Path) -> tuple[list[tuple[str, int]], list[int]]:
    text = path.read_text()

    dtypes: list[tuple[str, int]] = []
    seen_dtypes: set[str] = set()
    for name, value_text in re.findall(r"\.equ\s+(AME_[A-Z0-9_]+_DTYPE)\s*,\s*(0x[0-9a-fA-F]+|[0-9]+)", text):
        if name not in seen_dtypes:
            value = int(value_text, 0)
            dtypes.append((name, value & 0xFF))
            seen_dtypes.add(name)

    m_regs = sorted({int(reg) for reg in re.findall(r"\.equ\s+m([0-9]+)\s*,", text)})

    if not dtypes:
        raise ValueError(f"no AME dtype constants found in {path}")
    if not m_regs:
        raise ValueError(f"no AME m-register constants found in {path}")

    return dtypes, m_regs


def choose_aligned_m_reg(m_regs: list[int], case_id: int, element_bits: int, unit_bits: int) -> int:
    nregs = nregs_for_dtype(element_bits, unit_bits)
    candidates = [reg for reg in m_regs if reg % nregs == 0 and reg + nregs <= len(m_regs)]
    if not candidates:
        raise ValueError(f"no legal M register for element_bits={element_bits}, nregs={nregs}")
    return candidates[case_id % len(candidates)]


def supported_int_dtypes(dtypes: list[tuple[str, int]]) -> list[tuple[str, int]]:
    return [
        (name, bits)
        for name, bits in dtypes
        if (
            bits in {8, 16, 32, 64}
            and "_SAT_" not in name
            and not name.startswith("AME_FP")
            and not name.startswith("AME_BF")
            and not name.startswith("AME_OCP")
        )
    ]


def emit_mtype_roundtrip(dtypes: list[tuple[str, int]], m_regs: list[int], unit_bits: int = 8) -> str:
    lines = asm_header(
        [
            "Covers the currently implemented AME type-register path:",
            "  msettyp md, xs1",
            "  mgettyp xd, ms1",
        ]
    )

    for case_id, (dtype_name, element_bits) in enumerate(dtypes):
        m_reg = choose_aligned_m_reg(m_regs, case_id, element_bits, unit_bits)
        lines.extend(
            [
                f"    # case {case_id}: roundtrip {dtype_name} through m{m_reg}",
                f"    li    t0, {dtype_name}",
                f"    msettyp m{m_reg}, t0",
                f"    mgettyp t1, m{m_reg}",
                f"    EXPECT t1, {dtype_name}",
                "",
            ]
        )

    lines.extend(
        [
            "    RVMODEL_HALT_PASS",
            "",
        ]
    )
    return "\n".join(lines)


def emit_raw_load_store(dtype_name: str, element_bits: int, case_id: int) -> str:
    if element_bits not in {8, 16, 32, 64}:
        raise ValueError(f"unsupported raw load/store test element width: {element_bits}")

    directive = data_directive(element_bits)
    elem_bytes = element_bits // 8
    square_bytes = SQUARE_ELEMS * elem_bytes
    first = hex_value(0x11 + case_id, element_bits)
    second = hex_value(0x22 + case_id, element_bits)
    last = hex_value(0x33 + case_id, element_bits)

    lines = asm_header(
        [
            f"Raw square load/store coverage for {dtype_name}.",
            "Covers: msettyp, mls, mss.",
        ]
    )
    lines.extend(
        [
            f"    li      t0, {dtype_name}",
            "    msettyp m0, t0",
            "    la      t1, src_square",
            "    mls     m0, t1",
            "    la      t2, dst_square",
            "    mss     m0, t2",
            "",
            "    la      t3, dst_square",
            f"    lbu     t4, 0(t3)",
            f"    EXPECT  t4, {int(first, 16) & 0xFF}",
        ]
    )
    if elem_bytes > 1:
        lines.extend(
            [
                f"    lbu     t4, {elem_bytes}(t3)",
                f"    EXPECT  t4, {int(second, 16) & 0xFF}",
            ]
        )
    else:
        lines.extend(
            [
                "    lbu     t4, 1(t3)",
                f"    EXPECT  t4, {int(second, 16) & 0xFF}",
            ]
        )
    lines.extend(
        [
            f"    lbu     t4, {square_bytes - elem_bytes}(t3)",
            f"    EXPECT  t4, {int(last, 16) & 0xFF}",
            "",
            "    RVMODEL_HALT_PASS",
            "",
            ".data",
            f".balign {square_bytes}",
            "src_square:",
            f"    {directive} {first}",
            f"    {directive} {second}",
            f"    .rept {SQUARE_ELEMS - 3}",
            f"    {directive} 0",
            "    .endr",
            f"    {directive} {last}",
            f".balign {square_bytes}",
            "dst_square:",
            f"    .rept {square_bytes}",
            "    .byte 0xa5",
            "    .endr",
            "",
        ]
    )
    return "\n".join(lines)


def emit_acc_zero_move(dtype_name: str, element_bits: int, case_id: int) -> str:
    if element_bits not in {8, 16, 32, 64}:
        raise ValueError(f"unsupported acc zero/move test element width: {element_bits}")

    elem_bytes = element_bits // 8
    square_bytes = SQUARE_ELEMS * elem_bytes
    lines = asm_header(
        [
            f"Accumulator zero/move coverage for {dtype_name}.",
            "Covers: msettyp, asettyp, mzero.2d, mmov.a.m, mss.",
        ]
    )
    lines.extend(
        [
            f"    li      t0, {dtype_name}",
            "    msettyp m0, t0",
            "    asettyp acc0, t0",
            "    mzero.2d acc0",
            "    mmov.a.m m0, acc0",
            "    la      t1, dst_square",
            "    mss     m0, t1",
            "",
            "    la      t2, dst_square",
            "    lbu     t3, 0(t2)",
            "    EXPECT  t3, 0",
            f"    lbu     t3, {square_bytes - 1}(t2)",
            "    EXPECT  t3, 0",
            "",
            "    RVMODEL_HALT_PASS",
            "",
            ".data",
            f".balign {square_bytes}",
            "dst_square:",
            f"    .rept {square_bytes}",
            "    .byte 0xa5",
            "    .endr",
            "",
        ]
    )
    return "\n".join(lines)


def emit_mmulacc_2d(dtype_name: str, element_bits: int, case_id: int) -> str:
    if element_bits not in {8, 16, 32, 64}:
        raise ValueError(f"unsupported mmulacc.2d test element width: {element_bits}")

    directive = data_directive(element_bits)
    elem_bytes = element_bits // 8
    square_bytes = SQUARE_ELEMS * elem_bytes
    expected = hex_value(8, element_bits)
    expected_byte = int(expected, 16) & 0xFF
    b_reg = nregs_for_dtype(element_bits)

    lines = asm_header(
        [
            f"Integer matrix multiply-accumulate coverage for {dtype_name}.",
            "Covers: msettyp, asettyp, mls, mzero.2d, mmulacc.2d, mmov.a.m, mss.",
        ]
    )
    lines.extend(
        [
            f"    li      t0, {dtype_name}",
            "    msettyp m0, t0",
            f"    msettyp m{b_reg}, t0",
            "    asettyp acc0, t0",
            "",
            "    la      t1, a_square",
            "    mls     m0, t1",
            "    la      t2, b_square",
            f"    mls     m{b_reg}, t2",
            "    mzero.2d acc0",
            f"    mmulacc.2d acc0, m0, m{b_reg}",
            "    mmov.a.m m0, acc0",
            "    la      t3, c_square",
            "    mss     m0, t3",
            "",
            "    la      t4, c_square",
            "    lbu     t5, 0(t4)",
            f"    EXPECT  t5, {expected_byte}",
            f"    lbu     t5, {elem_bytes}(t4)",
            f"    EXPECT  t5, {expected_byte}",
            f"    lbu     t5, {square_bytes - elem_bytes}(t4)",
            f"    EXPECT  t5, {expected_byte}",
            "",
            "    RVMODEL_HALT_PASS",
            "",
            ".data",
            f".balign {square_bytes}",
            "a_square:",
            f"    .rept {SQUARE_ELEMS}",
            f"    {directive} 1",
            "    .endr",
            f".balign {square_bytes}",
            "b_square:",
            f"    .rept {SQUARE_ELEMS}",
            f"    {directive} 1",
            "    .endr",
            f".balign {square_bytes}",
            "c_square:",
            f"    .rept {square_bytes}",
            "    .byte 0xa5",
            "    .endr",
            "",
        ]
    )
    return "\n".join(lines)


def emit_manifest(dtypes: list[tuple[str, int]], m_regs: list[int], generated_files: list[str]) -> str:
    dtype_lines = "\n".join(f"  - {name}" for name, _ in dtypes)
    file_lines = "\n".join(f"  - {name}" for name in generated_files)
    return (
        "# Auto-generated by test/ame/gen/gen_ame_tests.py. Do not edit by hand.\n"
        "generator: test/ame/gen/gen_ame_tests.py\n"
        "suite: ame\n"
        f"dtype_count: {len(dtypes)}\n"
        f"m_register_count: {len(m_regs)}\n"
        "implemented_instruction_tests:\n"
        "  - msettyp/mgettyp\n"
        "  - mls/mss\n"
        "  - asettyp/mzero.2d/mmov.a.m\n"
        "  - mmulacc.2d\n"
        "generated_files:\n"
        f"{file_lines}\n"
        "dtype_constants:\n"
        f"{dtype_lines}\n"
    )


def main() -> int:
    parser = argparse.ArgumentParser(description="Generate AME bare-metal tests")
    parser.add_argument(
        "--sail-ame-root",
        type=Path,
        default=SAIL_AME_ROOT,
        help="Path to the sail-ame repository root",
    )
    parser.add_argument(
        "--out-dir",
        type=Path,
        required=True,
        help="Output directory for generated test files",
    )
    args = parser.parse_args()

    root = args.sail_ame_root.resolve()
    out_dir = args.out_dir.resolve()
    macro_path = root / "test/ame/src/ame_macros.inc"

    dtypes, m_regs = parse_ame_macros(macro_path)

    out_dir.mkdir(parents=True, exist_ok=True)

    generated: list[str] = []
    roundtrip_path = out_dir / "mtype_roundtrip.S"
    roundtrip_path.write_text(emit_mtype_roundtrip(dtypes, m_regs))
    generated.append(roundtrip_path.name)

    for case_id, (dtype_name, element_bits) in enumerate(supported_int_dtypes(dtypes)):
        stem = dtype_name.removeprefix("AME_").removesuffix("_DTYPE").lower()

        raw_path = out_dir / f"raw_load_store_{stem}.S"
        raw_path.write_text(emit_raw_load_store(dtype_name, element_bits, case_id))
        generated.append(raw_path.name)

        acc_path = out_dir / f"acc_zero_move_{stem}.S"
        acc_path.write_text(emit_acc_zero_move(dtype_name, element_bits, case_id))
        generated.append(acc_path.name)

        mmulacc_path = out_dir / f"mmulacc_2d_{stem}.S"
        mmulacc_path.write_text(emit_mmulacc_2d(dtype_name, element_bits, case_id))
        generated.append(mmulacc_path.name)

    manifest_path = out_dir / "manifest.yaml"
    manifest_path.write_text(emit_manifest(dtypes, m_regs, generated))

    print(f"Generated {len(generated)} AME test files in {out_dir}")
    print(f"Wrote {manifest_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
